import { readFileSync, writeFileSync } from 'node:fs';
import { compileNode } from 'zrow-js/node';

const result = compileNode({
  input: readFileSync('users.zrow', 'utf8'),
  mode: 'zrow',
  baseDir: process.cwd()
});

